package com.skyclone.mod.crimson;

import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;

import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.Reader;
import java.lang.reflect.Type;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.function.Function;

/**
 * The crimson module's own data files ({@code data/crimson/*.json}, generated by tools/gen/crimson),
 * as plain Gson objects. No Bukkit: unit tests load the same files from the test classpath.
 */
public final class CrimsonTables {

    // ---- npcs.json ----
    public static final class Npc {
        public String id, anchor, name, title, skin, role;
        public List<String> lines = new ArrayList<>();
    }

    // ---- quests.json ----
    public static final class Quest {
        public String id, type, target, faction, difficulty, desc;
        public int amount, rep, minRank;

        public boolean forFaction(String f) { return "any".equals(faction) || faction.equals(f); }
    }

    // ---- shop.json ----
    public static final class ShopEntry {
        public String item, faction;
        public double coins;
        public List<String> items = new ArrayList<>();
        public int rank;
        public int repMin;
        /** A Leviathan key sold by the faction's Emissary: its coin part is discounted by reputation (audit K17). */
        public boolean emissary;
    }

    // ---- factions.json ----
    public static final class Rank {
        public String name, color;
        public int rep, sbxp;
    }

    public static final class FactionInfo {
        public String display, color, leader, town, icon;
        public String rival_boss;
    }

    public static final class Factions {
        public List<Rank> ranks = new ArrayList<>();
        public Map<String, FactionInfo> factions = new LinkedHashMap<>();
        public int quests_per_day = 5;
        public int daily_bonus_rep = 0;
        public int boss_rep = 10;
        public int rival_boss_rep = 25;
        /** Wave 5: who shares a mini-boss kill and the faction-specific spoils. */
        public BossLoot boss_loot = new BossLoot();
        /** Reputation for the day's first Leviathan clear of each tier, Basic..Infernal (audit K16). */
        public List<Integer> kuudra_rep = new ArrayList<>(List.of(10, 20, 30, 40, 50));
        /** Emissary key discount: reputation threshold -> percent off the coin part (audit K17). */
        public Map<String, Integer> emissary_discount = new LinkedHashMap<>();
        /** Rollim's daily reputation (audit K18). */
        public Rollim rollim = new Rollim();
    }

    public static final class Rollim {
        public int rep = 25, days = 7, hours = 24;
    }

    /** One loot line of our own tables (the same shape as a MobDef drop). */
    public static final class LootLine {
        public String item;
        public int min = 1, max = 1;
        public double chance = 1.0;

        public LootLine() {}

        public LootLine(String item, int min, int max, double chance) {
            this.item = item; this.min = min; this.max = max; this.chance = chance;
        }
    }

    /**
     * Mini-boss spoils (wave 5, factions.json {@code boss_loot}). Every player who dealt at least
     * {@code min_damage_percent} of a mini-boss's health shares the kill; pledged players add their faction's
     * table, the rival faction's champion adds its {@code champion} table, and an open BOSS quest for that
     * boss adds the {@code quest} table. {@code shards}: boss -> the attribute shard the hunting module maps to it.
     */
    public static final class BossLoot {
        public double min_damage_percent = 1.0;
        public double max_range = 64;
        public Map<String, List<LootLine>> faction = new LinkedHashMap<>();
        public Map<String, List<LootLine>> champion = new LinkedHashMap<>();
        public List<LootLine> quest = new ArrayList<>();
        public Map<String, String> shards = new LinkedHashMap<>();
    }

    // ---- synthesizers (wave 5) ----
    /** One feedable stat of a Synthesizer: feeding {@code item} raises {@code stat} by 1 up to {@code cap}. */
    public static final class SynthSlot {
        public String item, stat;
        public int cap;
    }

    // ---- dojo.json ----
    public static final class Trial {
        public String id, name, icon;
        public int seconds;
        public List<String> how = new ArrayList<>();
    }

    public static final class DojoRank {
        public String rank;
        public int min;
    }

    public static final class Belt {
        public String id, name;
        public int points, sbxp;
    }

    public static final class Dojo {
        public List<Trial> trials = new ArrayList<>();
        public int max_points = 1000;
        public List<DojoRank> ranks = new ArrayList<>();
        public List<Belt> belts = new ArrayList<>();
    }

    public final List<Npc> npcs;
    public final List<Quest> quests;
    public final List<ShopEntry> shop;
    public final Factions factions;
    public final Dojo dojo;

    private CrimsonTables(List<Npc> npcs, List<Quest> quests, List<ShopEntry> shop, Factions factions, Dojo dojo) {
        this.npcs = npcs; this.quests = quests; this.shop = shop; this.factions = factions; this.dojo = dojo;
    }

    /** {@code open} maps a file name ("quests.json") to a stream (the jar resource in game, the test classpath in tests). */
    public static CrimsonTables load(Function<String, InputStream> open) {
        Gson g = new Gson();
        return new CrimsonTables(
                read(g, open, "npcs.json", new TypeToken<List<Npc>>() {}.getType(), new ArrayList<>()),
                read(g, open, "quests.json", new TypeToken<List<Quest>>() {}.getType(), new ArrayList<>()),
                read(g, open, "shop.json", new TypeToken<List<ShopEntry>>() {}.getType(), new ArrayList<>()),
                read(g, open, "factions.json", Factions.class, new Factions()),
                read(g, open, "dojo.json", Dojo.class, new Dojo()));
    }

    private static <T> T read(Gson g, Function<String, InputStream> open, String file, Type type, T fallback) {
        try (InputStream in = open.apply(file)) {
            if (in == null) return fallback;
            try (Reader r = new InputStreamReader(in, StandardCharsets.UTF_8)) {
                T v = g.fromJson(r, type);
                return v == null ? fallback : v;
            }
        } catch (IOException | RuntimeException e) {
            return fallback;
        }
    }

    public Quest quest(String id) {
        for (Quest q : quests) if (q.id.equals(id)) return q;
        return null;
    }

    public Trial trial(String id) {
        for (Trial t : dojo.trials) if (t.id.equals(id)) return t;
        return null;
    }

    public Npc npc(String id) {
        for (Npc n : npcs) if (n.id.equals(id)) return n;
        return null;
    }
}
